nextflow_process {

    name "Test Process KRAKENUNIQ_PRELOADEDKRAKENUNIQ"
    script "../main.nf"
    process "KRAKENUNIQ_PRELOADEDKRAKENUNIQ"
    tag "modules"
    tag "modules_nfcore"
    tag "krakenuniq"
    tag "krakenuniq/preloadedkrakenuniq"

    test("sarscov2 - FASTA") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/krakenuniq.tar.gz').resolve('krakenuniq')
        }

        when {
            params {
                outdir   = "$outputDir"
            }
            process {
                """
                input[0] = [
                    [id:'test', single_end:true],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.gz', checkIfExists: true),
                    ],
                    ['sample_1', 'sample.2']
                ]
                input[1] = 'fasta'
                input[2] = file('${db}')
                input[3] = true
                input[4] = true
                input[5] = true
                """
            }
        }

        then {
            def reports = process.out.report.get(0).get(1).collect { report -> file(report).name }
            def expected = ['sample_1.krakenuniq.report.txt', 'sample.2.krakenuniq.report.txt']

            assertAll (
                { assert process.success },
                // Report contains a timestamp.
                { assertContainsInAnyOrder(reports, expected) },
                { assert snapshot(
                    process.out.classified_reads,
                    process.out.unclassified_reads,
                    process.out.classified_assignment,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match('fasta') },
            )
        }

    }

